Write only Python: def interleave(a,b):
    out=[]; n=max(len(a),len(b))
    for i in range(n):
        if i<len(a): out.append(a[i])
        if i<len(b): out.append(b[i])
    return out
assert interleave([1,2],[9])==[1,9,2]
print(interleave([1,2],[9]))

Write only Python: def normalize_path(parts):
    stack=[]
    for p in parts:
        if p in ('', '.'): continue
        if p=='..':
            if stack: stack.pop()
        else: stack.append(p)
    return '/'+'/'.join(stack)
assert normalize_path(['a','b','..','c'])=='/a/c'
print(normalize_path(['a','b','..','c']))

Write only Python: def caesar(s,k):
    out=[]
    for ch in s:
        if ch.isalpha():
            base=ord('A') if ch.isupper() else ord('a')
            out.append(chr((ord(ch)-base+k)%26+base))
        else: out.append(ch)
    return ''.join(out)
assert caesar('ab',1)=='bc'
print(caesar('ab',1))
